module JC_counter(
    input clk, input rst_n,
    output reg [63:0] Q
);
    wire [63:0] Q_right_increment_shifting;
    wire [63:0] Q_right_decrement_shifting;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            Q <= 64'b0;
        else if (Q[0] == 1'b0)
            Q <= Q_right_increment_shifting;
        else
            Q <= Q_right_decrement_shifting;
    end

    assign Q_right_increment_shifting = {1'b1, Q[63:1]};
    assign Q_right_decrement_shifting = {1'b0, Q[63:1]};
endmodule
